import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../../store/hooks';
import {
  fetchTickets,
  fetchTicketStats,
  setFilters,
  setPage,
  setSelectedTicket,
} from '../../store/slices/ticketsSlice';
import {
  openSlideout,
  closeSlideout,
  resetCreateTicketForm,
  resetEditTicketForm,
} from '../../store/slices/uiSlice';
import { useResponsive } from '../../hooks/useResponsive';
import { UUID } from '../../models/common';
import { Button } from '../../components/common/Button';
import { Slideout } from '../../components/common/Slideout';
import { Pagination } from '../../components/common/Pagination';
import { TableCard } from '../../components/common/TableCard';
import { TicketStatsCards } from './components/TicketStatsCards';
import { TicketFilters } from './components/TicketFilters';
import { TicketTable } from './components/TicketTable';
import { CreateTicketForm } from './components/CreateTicketForm';
import { EditTicketForm } from '../../components/tickets/EditTicketForm';
import { AssignTicketModal } from '../../components/tickets/AssignTicketModal';
import { TriageTicketModal } from '../../components/tickets/TriageTicketModal';
import { Ticket } from '../../models/Ticket';
import styles from './TicketsListPage.module.css';

const TicketsListPage: React.FC = () => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { items, loading, filters, pagination, stats } = useAppSelector(
    (state) => state.tickets
  );
  const { slideouts } = useAppSelector((state) => state.ui);
  const { isMobile } = useResponsive();

  const [selectedTicketId, setSelectedTicketId] = useState<UUID | null>(null);
  const [assignModalOpen, setAssignModalOpen] = useState(false);
  const [triageModalOpen, setTriageModalOpen] = useState(false);
  const [ticketToAssign, setTicketToAssign] = useState<{ id: UUID; title: string } | null>(null);

  // Fetch tickets and stats on mount and when filters/page change
  useEffect(() => {
    const timer = setTimeout(() => { dispatch(fetchTickets(filters)); }, 0);
    return () => clearTimeout(timer);
  }, [dispatch, filters, pagination.page]);

  useEffect(() => {
    const timer = setTimeout(() => { dispatch(fetchTicketStats()); }, 0);
    return () => clearTimeout(timer);
  }, [dispatch]);

  // Handlers
  const handleFilterChange = (newFilters: typeof filters) => {
    dispatch(setFilters(newFilters));
    dispatch(setPage(1)); // Reset to first page on filter change
  };

  const handleCreateClick = () => {
    dispatch(openSlideout('createTicket'));
  };

  const handleView = (ticket: Ticket) => {
    navigate(`/tickets/${ticket.id}`);
  };

  const handleEdit = (ticket: Ticket) => {
    setSelectedTicketId(ticket.id);
    dispatch(openSlideout('editTicket'));
  };

  const handleAssign = (ticket: Ticket) => {
    setTicketToAssign({ id: ticket.id, title: ticket.title });
    setAssignModalOpen(true);
  };

  const handleTriage = (ticket: Ticket) => {
    dispatch(setSelectedTicket(ticket)); // populate before modal mounts
    setSelectedTicketId(ticket.id);
    setTriageModalOpen(true);
  };

  const handleTriageSuccess = () => {
    setTriageModalOpen(false);
    setSelectedTicketId(null);
    dispatch(fetchTickets(filters));
    dispatch(fetchTicketStats());
  };

  const handleAssignSuccess = () => {
    setAssignModalOpen(false);
    setTicketToAssign(null);
    dispatch(fetchTickets(filters));
    dispatch(fetchTicketStats());
  };

  const handleCreateSuccess = () => {
    dispatch(closeSlideout('createTicket'));
    dispatch(resetCreateTicketForm());
    dispatch(fetchTickets(filters));
    dispatch(fetchTicketStats());
  };

  const handleEditSuccess = () => {
    dispatch(closeSlideout('editTicket'));
    dispatch(resetEditTicketForm());
    dispatch(fetchTickets(filters));
    dispatch(fetchTicketStats());
  };

  const totalPages = Math.ceil(pagination.totalCount / pagination.pageSize);

  return (
    <div className={styles.page}>
      {/* Page Header */}
      <div className={styles.header}>
        <h1 className={styles.title}>
          <i className="fas fa-ticket-alt"></i>
          Quản Lý Phiếu Yêu Cầu
        </h1>
        <Button variant="primary" onClick={handleCreateClick}>
          <i className="fas fa-plus"></i>
          {!isMobile && ' Tạo Ticket Mới'}
        </Button>
      </div>

      {/* Statistics Cards */}
      <TicketStatsCards stats={stats} loading={loading} />

      {/* Main Content Card */}
      <TableCard
        header={<TicketFilters filters={filters} onChange={handleFilterChange} />}
        footer={
          !loading && items.length > 0 ? (
            <Pagination
              currentPage={pagination.page}
              totalPages={totalPages}
              totalCount={pagination.totalCount}
              pageSize={pagination.pageSize}
              itemLabel="tickets"
              onPageChange={(page) => dispatch(setPage(page))}
            />
          ) : undefined
        }
      >
        <TicketTable
          tickets={items}
          loading={loading}
          onView={handleView}
          onEdit={handleEdit}
          onAssign={handleAssign}
          onTriage={handleTriage}
        />
      </TableCard>

      {/* Slideouts */}
      <Slideout
        isOpen={slideouts.createTicket}
        onClose={() => {
          dispatch(closeSlideout('createTicket'));
          dispatch(resetCreateTicketForm());
        }}
        title="Tạo Ticket Mới"
        width={isMobile ? '100%' : '600px'}
      >
        <CreateTicketForm
          onSuccess={handleCreateSuccess}
          onCancel={() => {
            dispatch(closeSlideout('createTicket'));
            dispatch(resetCreateTicketForm());
          }}
        />
      </Slideout>

      <Slideout
        isOpen={slideouts.editTicket}
        onClose={() => {
          dispatch(closeSlideout('editTicket'));
          dispatch(resetEditTicketForm());
        }}
        title="Chỉnh Sửa Ticket"
        width={isMobile ? '100%' : '600px'}
      >
        {selectedTicketId && (
          <EditTicketForm
            ticketId={selectedTicketId}
            onSuccess={handleEditSuccess}
            onCancel={() => {
              dispatch(closeSlideout('editTicket'));
              dispatch(resetEditTicketForm());
            }}
          />
        )}
      </Slideout>

      {/* Assign Modal */}
      {ticketToAssign && (
        <AssignTicketModal
          isOpen={assignModalOpen}
          ticketId={ticketToAssign.id}
          ticketTitle={ticketToAssign.title}
          onClose={() => {
            setAssignModalOpen(false);
            setTicketToAssign(null);
          }}
          onSuccess={handleAssignSuccess}
        />
      )}

      {/* Triage Modal */}
      {selectedTicketId && (
        <TriageTicketModal
          isOpen={triageModalOpen}
          ticketId={selectedTicketId}
          onClose={() => {
            setTriageModalOpen(false);
            setSelectedTicketId(null);
          }}
          onSuccess={handleTriageSuccess}
        />
      )}
    </div>
  );
};

export default TicketsListPage;
