import React, { useEffect, useRef, useState } from 'react';
import mermaid from 'mermaid';
import { ZoomControls } from '../ZoomControls';
import styles from './WorkflowDiagram.module.css';

interface WorkflowDiagramProps {
  diagramCode: string;
  type: 'ticket' | 'task' | 'incident';
}

const MIN_ZOOM = 0.1;
const MAX_ZOOM = 5;
const ZOOM_STEP = 0.15;
const INITIAL_PAD = 24;

const initMermaid = () => {
  mermaid.initialize({
    startOnLoad: false,
    theme: 'default',
    securityLevel: 'loose',
    flowchart: { useMaxWidth: true, htmlLabels: false, curve: 'basis' },
  });
};
initMermaid();

export const WorkflowDiagram: React.FC<WorkflowDiagramProps> = ({ diagramCode, type }) => {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: INITIAL_PAD, y: INITIAL_PAD });
  const [isDragging, setIsDragging] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isRendering, setIsRendering] = useState(true);

  // Refs for current values — avoids stale closures in event handlers
  const zoomRef = useRef(zoom);
  const panRef = useRef(pan);
  zoomRef.current = zoom;
  panRef.current = pan;

  const dragStart = useRef<{ mouseX: number; mouseY: number; panX: number; panY: number } | null>(null);
  // For pinch-to-zoom: track last distance between two touches
  const lastPinchDist = useRef<number | null>(null);

  // Render whenever diagram code changes
  useEffect(() => { renderDiagram(); }, [diagramCode]);

  // Non-passive wheel handler for scroll-to-zoom
  useEffect(() => {
    const el = wrapperRef.current;
    if (!el) return;
    const onWheel = (e: WheelEvent) => {
      e.preventDefault();
      const rect = el.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;
      const factor = e.deltaY < 0 ? 1.1 : 1 / 1.1;
      const cur = zoomRef.current;
      const newZoom = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, cur * factor));
      const sf = newZoom / cur;
      const p = panRef.current;
      setZoom(newZoom);
      setPan({ x: mx - (mx - p.x) * sf, y: my - (my - p.y) * sf });
    };
    el.addEventListener('wheel', onWheel, { passive: false });

    // Non-passive touch handler to prevent page scroll while interacting
    const onTouchMove = (e: TouchEvent) => {
      if (e.touches.length === 1 && dragStart.current) {
        // Single finger pan
        e.preventDefault();
      } else if (e.touches.length === 2) {
        // Pinch-to-zoom
        e.preventDefault();
        const t0 = e.touches[0];
        const t1 = e.touches[1];
        const dist = Math.hypot(t1.clientX - t0.clientX, t1.clientY - t0.clientY);
        if (lastPinchDist.current !== null) {
          const rect = el.getBoundingClientRect();
          const midX = (t0.clientX + t1.clientX) / 2 - rect.left;
          const midY = (t0.clientY + t1.clientY) / 2 - rect.top;
          const factor = dist / lastPinchDist.current;
          const cur = zoomRef.current;
          const newZoom = Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, cur * factor));
          const sf = newZoom / cur;
          const p = panRef.current;
          setZoom(newZoom);
          setPan({ x: midX - (midX - p.x) * sf, y: midY - (midY - p.y) * sf });
        }
        lastPinchDist.current = dist;
      }
    };
    el.addEventListener('touchmove', onTouchMove, { passive: false });

    return () => {
      el.removeEventListener('wheel', onWheel);
      el.removeEventListener('touchmove', onTouchMove);
    };
  }, []);

  /** Fit the rendered SVG inside the wrapper, centred with padding. */
  const fitToViewport = () => {
    const wrapper = wrapperRef.current;
    const container = containerRef.current;
    if (!wrapper || !container) return;
    const svg = container.querySelector('svg');
    if (!svg) return;

    const pad = INITIAL_PAD * 2;
    const vw = wrapper.clientWidth  - pad;
    const vh = wrapper.clientHeight - pad;

    // Use the SVG's intrinsic size (viewBox or width/height attrs)
    const svgW = svg.width?.baseVal?.value  || svg.viewBox?.baseVal?.width  || container.scrollWidth;
    const svgH = svg.height?.baseVal?.value || svg.viewBox?.baseVal?.height || container.scrollHeight;

    if (!svgW || !svgH) return;

    const fitZoom = Math.min(vw / svgW, vh / svgH, MAX_ZOOM);
    const clampedZoom = Math.max(MIN_ZOOM, fitZoom);

    // Centre within the wrapper
    const panX = (wrapper.clientWidth  - svgW * clampedZoom) / 2;
    const panY = (wrapper.clientHeight - svgH * clampedZoom) / 2;

    setZoom(clampedZoom);
    setPan({ x: Math.max(INITIAL_PAD, panX), y: Math.max(INITIAL_PAD, panY) });
  };

  const renderDiagram = async () => {
    if (!containerRef.current) return;
    try {
      setIsRendering(true);
      setError(null);
      initMermaid();
      containerRef.current.innerHTML = '';
      const id = `mermaid-${type}-${Date.now()}`;
      const { svg } = await mermaid.render(id, diagramCode);
      if (containerRef.current) {
        containerRef.current.innerHTML = svg;
        // Defer so the browser has laid out the SVG before we measure
        requestAnimationFrame(() => requestAnimationFrame(fitToViewport));
      }
    } catch (err) {
      console.error('Mermaid render error:', err);
      setError('Không thể hiển thị sơ đồ');
    } finally {
      setIsRendering(false);
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return;
    e.preventDefault();
    setIsDragging(true);
    dragStart.current = { mouseX: e.clientX, mouseY: e.clientY, panX: panRef.current.x, panY: panRef.current.y };
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!dragStart.current) return;
    const { mouseX, mouseY, panX, panY } = dragStart.current;
    setPan({ x: panX + (e.clientX - mouseX), y: panY + (e.clientY - mouseY) });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    dragStart.current = null;
  };

  // Touch handlers
  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 1) {
      const t = e.touches[0];
      setIsDragging(true);
      dragStart.current = { mouseX: t.clientX, mouseY: t.clientY, panX: panRef.current.x, panY: panRef.current.y };
      lastPinchDist.current = null;
    } else if (e.touches.length === 2) {
      dragStart.current = null;
      lastPinchDist.current = Math.hypot(
        e.touches[1].clientX - e.touches[0].clientX,
        e.touches[1].clientY - e.touches[0].clientY,
      );
    }
  };

  const handleTouchMove = (e: React.TouchEvent) => {
    if (e.touches.length === 1 && dragStart.current) {
      const t = e.touches[0];
      const { mouseX, mouseY, panX, panY } = dragStart.current;
      setPan({ x: panX + (t.clientX - mouseX), y: panY + (t.clientY - mouseY) });
    }
    // Pinch zoom is handled in the non-passive native listener
  };

  const handleTouchEnd = () => {
    setIsDragging(false);
    dragStart.current = null;
    lastPinchDist.current = null;
  };

  const zoomToCenter = (newZoom: number) => {
    const el = wrapperRef.current;
    if (!el) return;
    const cx = el.clientWidth / 2;
    const cy = el.clientHeight / 2;
    const f = newZoom / zoomRef.current;
    setPan({ x: cx - (cx - panRef.current.x) * f, y: cy - (cy - panRef.current.y) * f });
    setZoom(newZoom);
  };

  const handleZoomIn    = () => zoomToCenter(Math.min(MAX_ZOOM, zoom + ZOOM_STEP));
  const handleZoomOut   = () => zoomToCenter(Math.max(MIN_ZOOM, zoom - ZOOM_STEP));
  const handleResetZoom = () => fitToViewport();

  const handleFullscreen = () => {
    if (!wrapperRef.current) return;
    if (document.fullscreenElement) document.exitFullscreen();
    else wrapperRef.current.requestFullscreen();
  };

  if (error) {
    return (
      <div className={styles.error}>
        <span>⚠️</span>
        <p>{error}</p>
      </div>
    );
  }

  return (
    <div className={styles.wrapper}>
      <ZoomControls
        zoom={zoom}
        onZoomIn={handleZoomIn}
        onZoomOut={handleZoomOut}
        onResetZoom={handleResetZoom}
        onFullscreen={handleFullscreen}
        minZoom={MIN_ZOOM}
        maxZoom={MAX_ZOOM}
      />
      <div
        ref={wrapperRef}
        className={`${styles.diagramWrapper} ${isDragging ? styles.dragging : ''}`}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleTouchEnd}
        onTouchCancel={handleTouchEnd}
      >
        {isRendering && <div className={styles.loading}>Đang tạo sơ đồ...</div>}
        <div
          ref={containerRef}
          className={styles.diagram}
          style={{ transform: `translate(${pan.x}px, ${pan.y}px) scale(${zoom})`, transformOrigin: '0 0' }}
        />
      </div>
    </div>
  );
};
