import React from 'react';
import styles from './FormActions.module.css';

export interface FormActionsProps {
  children: React.ReactNode;
  /** Number of columns on mobile (default: 2) */
  mobileColumns?: 1 | 2;
  /** Alignment of buttons (default: 'end' for submit buttons, 'stretch' for action buttons) */
  align?: 'start' | 'center' | 'end' | 'stretch';
  className?: string;
}

/**
 * FormActions Component
 * 
 * Responsive container for form buttons and action items:
 * - Desktop: Displays buttons horizontally
 * - Mobile: Displays in a grid with configurable columns (default: 2 per row)
 * 
 * Usage examples:
 * ```tsx
 * // Submit buttons (aligned to end)
 * <FormActions align="end">
 *   <Button variant="secondary">Cancel</Button>
 *   <Button variant="primary">Save</Button>
 * </FormActions>
 * 
 * // Action selection (full width buttons)
 * <FormActions align="stretch">
 *   <ActionButton>Accept</ActionButton>
 *   <ActionButton>Request Info</ActionButton>
 *   <ActionButton>Reject</ActionButton>
 * </FormActions>
 * ```
 */
export const FormActions: React.FC<FormActionsProps> = ({
  children,
  mobileColumns = 2,
  align = 'end',
  className = '',
}) => {
  const alignClass = styles[`align-${align}`] || styles['align-end'];
  const mobileClass = styles[`mobile-cols-${mobileColumns}`] || styles['mobile-cols-2'];

  return (
    <div className={`${styles.formActions} ${alignClass} ${mobileClass} ${className}`}>
      {children}
    </div>
  );
};
