import React, { useState, useMemo, useRef, useCallback, useEffect } from 'react';
import { Input } from '../../../components/common/Input';
import { Select, SelectOption } from '../../../components/common/Select';
import { DateRangeFilter } from '../../../components/common/DateRangeFilter';
import {
  MedicalIncidentFilters,
  IncidentStatus,
  IncidentSeverity,
  IncidentReportType,
} from '../../../models/MedicalIncident';
import { useResponsive } from '../../../hooks/useResponsive';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './MedicalIncidentFiltersBar.module.css';

interface Props {
  filters: MedicalIncidentFilters;
  onChange: (f: MedicalIncidentFilters) => void;
  onClear: () => void;
}

export const MedicalIncidentFiltersBar: React.FC<Props> = ({
  filters,
  onChange,
  onClear,
}) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);

  const {
    departmentOptions,
    incidentStatusOptions,
    incidentSeverityOptions,
    incidentReportTypeOptions,
  } = useFormOptions('incident-list');

  const allStatusOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả trạng thái' }, ...incidentStatusOptions],
    [incidentStatusOptions],
  );

  const allSeverityOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả mức độ' }, ...incidentSeverityOptions],
    [incidentSeverityOptions],
  );

  const allDeptOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả khoa' }, ...departmentOptions],
    [departmentOptions],
  );

  const allReportTypeOptions: SelectOption[] = useMemo(
    () => [{ value: '', label: 'Tất cả hình thức' }, ...incidentReportTypeOptions],
    [incidentReportTypeOptions],
  );

  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (filters.search)       count++;
    if (filters.status)       count++;
    if (filters.severity)     count++;
    if (filters.departmentId) count++;
    if (filters.reportType)   count++;
    if (filters.dateFrom || filters.dateTo) count++;
    return count;
  }, [filters]);

  const hasActiveFilters = activeFilterCount > 0;

  const buttonRef = useRef<HTMLButtonElement>(null);
  const [dropdownStyle, setDropdownStyle] = useState<React.CSSProperties>({});

  const computeDropdownStyle = useCallback(() => {
    if (!buttonRef.current) return;
    const rect = buttonRef.current.getBoundingClientRect();
    const panelWidth = Math.min(300, window.innerWidth - 16);
    const centeredLeft = Math.max(8, (window.innerWidth - panelWidth) / 2);
    setDropdownStyle({
      top: rect.bottom + 8,
      left: centeredLeft,
      width: panelWidth,
    });
  }, []);

  const handleToggle = () => {
    if (!isExpanded) computeDropdownStyle();
    setIsExpanded((v) => !v);
  };
  const handleClose = () => setIsExpanded(false);

  useEffect(() => {
    if (!isExpanded) return;
    const close = () => setIsExpanded(false);
    window.addEventListener('scroll', close, { passive: true, capture: true });
    window.addEventListener('resize', close, { passive: true });
    return () => {
      window.removeEventListener('scroll', close, { capture: true });
      window.removeEventListener('resize', close);
    };
  }, [isExpanded]);

  // ── Mobile: toggle button + backdrop + dropdown panel ──────────────────────
  if (isMobile) {
    return (
      <>
        {isExpanded && (
          <div className={styles.filterBackdrop} onClick={handleClose} />
        )}

        <div className={styles.filterDropdownWrapper}>
          <button
            ref={buttonRef}
            className={styles.filterToggle}
            onClick={handleToggle}
            aria-expanded={isExpanded}
            aria-label="Toggle filters"
            type="button"
          >
            <i className="fas fa-filter" />
            <span>Lọc</span>
            {activeFilterCount > 0 && (
              <span className={styles.filterBadge}>{activeFilterCount}</span>
            )}
            <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`} />
          </button>

          {isExpanded && (
            <div className={styles.mobileFilters} style={dropdownStyle}>
              <DateRangeFilter
                fromDate={filters.dateFrom}
                toDate={filters.dateTo}
                onChange={(val) => onChange({ ...filters, dateFrom: val.fromDate, dateTo: val.toDate })}
              />
              <Input
                placeholder="Tìm kiếm mã, tên sự cố, bệnh nhân..."
                value={filters.search ?? ''}
                onChange={(e) => onChange({ ...filters, search: e.target.value })}
                size="small"
              />
              <Select
                options={allStatusOptions}
                value={filters.status ?? ''}
                onChange={(e) =>
                  onChange({ ...filters, status: e.target.value as IncidentStatus | '' })
                }
                size="small"
                fullWidth
              />
              <Select
                options={allSeverityOptions}
                value={filters.severity ?? ''}
                onChange={(e) =>
                  onChange({ ...filters, severity: e.target.value as IncidentSeverity | '' })
                }
                size="small"
                fullWidth
              />
              <Select
                options={allDeptOptions}
                value={filters.departmentId ?? ''}
                onChange={(e) => onChange({ ...filters, departmentId: e.target.value })}
                size="small"
                fullWidth
              />
              <Select
                options={allReportTypeOptions}
                value={filters.reportType ?? ''}
                onChange={(e) =>
                  onChange({ ...filters, reportType: e.target.value as IncidentReportType | '' })
                }
                size="small"
                fullWidth
              />
              {hasActiveFilters && (
                <button
                  className={styles.clearFiltersButton}
                  onClick={() => { onClear(); handleClose(); }}
                  type="button"
                >
                  <i className="fas fa-times-circle" />
                  <span>Xóa bộ lọc</span>
                </button>
              )}
            </div>
          )}
        </div>
      </>
    );
  }

  // ── Desktop: horizontal row ─────────────────────────────────────────────────
  return (
    <div className={styles.filters}>
      <DateRangeFilter
        fromDate={filters.dateFrom}
        toDate={filters.dateTo}
        onChange={(val) => onChange({ ...filters, dateFrom: val.fromDate, dateTo: val.toDate })}
      />
      <Input
        placeholder="Tìm kiếm mã, tên sự cố, bệnh nhân..."
        value={filters.search ?? ''}
        onChange={(e) => onChange({ ...filters, search: e.target.value })}
        size="small"
        className={styles.searchInput}
      />
      <Select
        options={allStatusOptions}
        value={filters.status ?? ''}
        onChange={(e) =>
          onChange({ ...filters, status: e.target.value as IncidentStatus | '' })
        }
        size="small"
      />
      <Select
        options={allSeverityOptions}
        value={filters.severity ?? ''}
        onChange={(e) =>
          onChange({ ...filters, severity: e.target.value as IncidentSeverity | '' })
        }
        size="small"
      />
      <Select
        options={allDeptOptions}
        value={filters.departmentId ?? ''}
        onChange={(e) => onChange({ ...filters, departmentId: e.target.value })}
        size="small"
      />
      <Select
        options={allReportTypeOptions}
        value={filters.reportType ?? ''}
        onChange={(e) =>
          onChange({ ...filters, reportType: e.target.value as IncidentReportType | '' })
        }
        size="small"
      />
      {hasActiveFilters && (
        <button
          className={styles.clearFiltersButtonDesktop}
          onClick={onClear}
          type="button"
          title="Xóa bộ lọc"
        >
          <i className="fas fa-times-circle" />
          <span>Xóa bộ lọc</span>
        </button>
      )}
    </div>
  );
};
