/**
 * Conversation inbox endpoint.
 * Calls GET /web-bff/api/v1/messages/conversations
 */
import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import { ConversationPagedResult } from './conversationTypes';

export const conversationEndpoint = {
  /**
   * GET /messages/conversations?page=1&pageSize=20&entityType=ticket|task
   * Returns paged list of conversations for the current user.
   */
  getConversations: async (
    page:       number = 1,
    pageSize:   number = 20,
    entityType?: 'ticket' | 'task' | 'incident',
  ): Promise<ConversationPagedResult> => {
    const params = new URLSearchParams();
    params.append('page', page.toString());
    params.append('pageSize', pageSize.toString());
    if (entityType) params.append('entityType', entityType);

    const res = await apiClient.get<BffResponse<ConversationPagedResult>>(
      `/messages/conversations?${params.toString()}`,
    );
    return unwrap(res);
  },

  /**
   * PATCH /messages/conversations/{entityType}/{entityId}/read
   * Updates LastReadAt on the subscription row so unread count resets to 0.
   */
  markConversationRead: async (
    entityType: 'ticket' | 'task' | 'incident',
    entityId: string,
  ): Promise<void> => {
    await apiClient.patch(
      `/messages/conversations/${entityType}/${entityId}/read`,
      {}
    );
  },
};
