/**
 * DateRangeFilter — common component
 *
 * Provides quick-select date presets plus a custom from/to date picker.
 *
 * Props:
 *   fromDate  — ISO date string "YYYY-MM-DD" or undefined
 *   toDate    — ISO date string "YYYY-MM-DD" or undefined
 *   onChange  — called whenever the range changes
 *
 * Presets: Hôm nay | Tuần này | Tháng này | Chọn ngày (custom from-to)
 */
import React, { useEffect, useState } from 'react';
import { Input } from '../Input';
import styles from './DateRangeFilter.module.css';

export type DatePreset = 'today' | 'this-week' | 'this-month' | 'custom' | '';

export interface DateRangeValue {
  fromDate?: string;
  toDate?:   string;
}

interface Props {
  fromDate?: string;
  toDate?:   string;
  onChange:  (value: DateRangeValue) => void;
  /** If true, renders inline (no dropdown wrapper). Default false. */
  inline?:   boolean;
}

// ── helpers ──────────────────────────────────────────────────────────────────

function toISODate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

function getPresetRange(preset: DatePreset): DateRangeValue {
  const today = new Date();
  if (preset === 'today') {
    const s = toISODate(today);
    return { fromDate: s, toDate: s };
  }
  if (preset === 'this-week') {
    const day  = today.getDay() === 0 ? 6 : today.getDay() - 1; // Mon=0
    const mon  = new Date(today); mon.setDate(today.getDate() - day);
    const sun  = new Date(mon);   sun.setDate(mon.getDate() + 6);
    return { fromDate: toISODate(mon), toDate: toISODate(sun) };
  }
  if (preset === 'this-month') {
    const first = new Date(today.getFullYear(), today.getMonth(), 1);
    const last  = new Date(today.getFullYear(), today.getMonth() + 1, 0);
    return { fromDate: toISODate(first), toDate: toISODate(last) };
  }
  return {};
}

function detectPreset(fromDate?: string, toDate?: string): DatePreset {
  if (!fromDate && !toDate) return '';
  const today = toISODate(new Date());
  if (fromDate === today && toDate === today) return 'today';
  const tw = getPresetRange('this-week');
  if (fromDate === tw.fromDate && toDate === tw.toDate) return 'this-week';
  const tm = getPresetRange('this-month');
  if (fromDate === tm.fromDate && toDate === tm.toDate) return 'this-month';
  return 'custom';
}

const PRESETS: { value: DatePreset; label: string }[] = [
  { value: '',           label: 'Tất cả ngày' },
  { value: 'today',      label: 'Hôm nay' },
  { value: 'this-week',  label: 'Tuần này' },
  { value: 'this-month', label: 'Tháng này' },
  { value: 'custom',     label: 'Chọn ngày…' },
];

// ── Component ─────────────────────────────────────────────────────────────────

export const DateRangeFilter: React.FC<Props> = ({
  fromDate,
  toDate,
  onChange,
}) => {
  const [activePreset, setActivePreset] = useState<DatePreset>(() =>
    detectPreset(fromDate, toDate),
  );

  // Sync preset when parent clears filters externally
  useEffect(() => {
    setActivePreset(detectPreset(fromDate, toDate));
  }, [fromDate, toDate]);

  const handlePreset = (preset: DatePreset) => {
    setActivePreset(preset);
    if (preset === '' || preset === 'custom') {
      // '' clears, 'custom' reveals the pickers but keeps current values until user picks
      if (preset === '') onChange({ fromDate: undefined, toDate: undefined });
    } else {
      onChange(getPresetRange(preset));
    }
  };

  const handleFrom = (e: React.ChangeEvent<HTMLInputElement>) => {
    setActivePreset('custom');
    onChange({ fromDate: e.target.value || undefined, toDate });
  };

  const handleTo = (e: React.ChangeEvent<HTMLInputElement>) => {
    setActivePreset('custom');
    onChange({ fromDate, toDate: e.target.value || undefined });
  };

  return (
    <div className={styles.wrapper}>
      {/* Preset dropdown */}
      <select
        className={styles.select}
        value={activePreset}
        onChange={(e) => handlePreset(e.target.value as DatePreset)}
        aria-label="Lọc theo ngày"
      >
        {PRESETS.map((p) => (
          <option key={p.value} value={p.value}>{p.label}</option>
        ))}
      </select>

      {/* Custom date pickers — shown only when 'Chọn ngày' is selected */}
      {activePreset === 'custom' && (
        <div className={styles.customPickers}>
          <Input
            type="date"
            size="small"
            value={fromDate ?? ''}
            onChange={handleFrom}
            placeholder="Từ ngày"
            aria-label="Từ ngày"
          />
          <span className={styles.sep}>→</span>
          <Input
            type="date"
            size="small"
            value={toDate ?? ''}
            onChange={handleTo}
            placeholder="Đến ngày"
            aria-label="Đến ngày"
          />
        </div>
      )}
    </div>
  );
};
