/**
 * TicketPerformanceReport Component
 * Displays ticket performance metrics and trends
 */

import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Filler,
  Tooltip,
  Legend,
} from 'chart.js';
import { Line } from 'react-chartjs-2';
import type { TicketPerformanceMetrics } from '../../../models/Report';
import styles from './TicketPerformanceReport.module.css';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Filler,
  Tooltip,
  Legend
);

interface TicketPerformanceReportProps {
  data: TicketPerformanceMetrics;
}

export const TicketPerformanceReport: React.FC<TicketPerformanceReportProps> = ({
  data,
}) => {
  const chartData = {
    labels: data.trend.map((point) => point.label),
    datasets: [
      {
        label: 'Phiếu Yêu Cầu Đã Xử Lý',
        data: data.trend.map((point) => point.value),
        borderColor: '#10b981',
        backgroundColor: 'rgba(16, 185, 129, 0.1)',
        tension: 0.4,
        fill: true,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: false,
      },
    },
    scales: {
      y: {
        beginAtZero: true,
      },
    },
  };

  return (
    <div className={styles.reportCard}>
      <div className={styles.cardHeader}>
        <h3 className={styles.cardTitle}>
          <i className="fas fa-ticket-alt"></i>
          Hiệu Suất Phiếu Yêu Cầu
        </h3>
        <button className={styles.exportButton}>
          <i className="fas fa-download"></i>
        </button>
      </div>
      <div className={styles.cardBody}>
        <div className={styles.statsGrid}>
          <div className={`${styles.statCard} ${styles.blue}`}>
            <div className={styles.statLabel}>Tổng tickets</div>
            <div className={styles.statValue}>{data.totalTickets}</div>
          </div>
          <div className={`${styles.statCard} ${styles.green}`}>
            <div className={styles.statLabel}>Đã hoàn thành</div>
            <div className={styles.statValue}>{data.resolvedTickets}</div>
          </div>
          <div className={`${styles.statCard} ${styles.yellow}`}>
            <div className={styles.statLabel}>Thời gian TB</div>
            <div className={styles.statValue}>{data.averageTimeHours}h</div>
          </div>
          <div className={`${styles.statCard} ${styles.purple}`}>
            <div className={styles.statLabel}>Tỷ lệ đạt</div>
            <div className={styles.statValue}>{data.completionRate}%</div>
          </div>
        </div>
        <div className={styles.chartContainer}>
          <Line data={chartData} options={chartOptions} />
        </div>
      </div>
    </div>
  );
};
