import React, { useState, useMemo } from 'react';
import { TaskFilters as ITaskFilters } from '../../../models/Task';
import { Select, SelectOption } from '../../../components/common/Select';
import { Input } from '../../../components/common/Input';
import { useResponsive } from '../../../hooks/useResponsive';
import { useFormOptions } from '../../../hooks/useFormOptions';
import styles from './TaskFilters.module.css';

interface TaskFiltersProps {
  filters: ITaskFilters;
  onFilterChange: (filters: ITaskFilters) => void;
}

type SourceFilter = '' | 'created_by_me' | 'from_pool' | 'assigned_by_manager';

const SOURCE_OPTIONS: { value: SourceFilter; label: string; icon: string }[] = [
  { value: '',                    label: 'Tất cả',                              icon: 'fa-list' },
  { value: 'created_by_me',       label: 'Công việc của tôi tạo',               icon: 'fa-pen' },
  { value: 'from_pool',           label: 'Nhận từ kho',                         icon: 'fa-inbox' },
  { value: 'assigned_by_manager', label: 'Được assign từ quản lý',              icon: 'fa-user-tie' },
];

export const TaskFiltersComponent: React.FC<TaskFiltersProps> = ({
  filters,
  onFilterChange,
}) => {
  const { isMobile } = useResponsive();
  const [isExpanded, setIsExpanded] = useState(false);
  const { taskPriorityOptions, assignmentStrategyOptions, taskStatusOptions } = useFormOptions('task-list');

  const allPriorityOptions = useMemo<SelectOption[]>(
    () => [{ value: '', label: 'Tất cả ưu tiên' }, ...taskPriorityOptions],
    [taskPriorityOptions]
  );

  const allStatusOptions = useMemo<SelectOption[]>(
    () => [{ value: '', label: 'Tất cả trạng thái' }, ...taskStatusOptions],
    [taskStatusOptions]
  );

  const allStrategyOptions = useMemo<SelectOption[]>(
    () => [{ value: '', label: 'Tất cả phân công' }, ...assignmentStrategyOptions],
    [assignmentStrategyOptions]
  );

  // Count active filters (excluding search which is always visible)
  const activeFilterCount = useMemo(() => {
    let count = 0;
    if (filters.priority)           count++;
    if (filters.status)             count++;
    if (filters.assignmentStrategy) count++;
    return count;
  }, [filters]);

  const handleChange = (key: keyof ITaskFilters, value: any) => {
    onFilterChange({ ...filters, [key]: value || undefined });
  };

  const handleSourceChange = (value: SourceFilter) => {
    onFilterChange({ ...filters, source: value || undefined });
  };

  const handleToggle = () => {
    setIsExpanded(!isExpanded);
  };

  const handleClose = () => {
    setIsExpanded(false);
  };

  const handleClearFilters = () => {
    onFilterChange({
      search: '',
      priority:           undefined,
      status:             undefined,
      assignmentStrategy: undefined,
      source:             undefined,
    });
  };

  const hasActiveFilters = useMemo(() => {
    return !!(filters.priority || filters.status || filters.search || filters.assignmentStrategy || filters.source);
  }, [filters]);

  const currentSource = (filters.source ?? '') as SourceFilter;

  const sourcePills = (
    <div className={styles.sourcePills}>
      {SOURCE_OPTIONS.map((opt) => (
        <button
          key={opt.value}
          type="button"
          className={`${styles.sourcePill} ${currentSource === opt.value ? styles.sourcePillActive : ''}`}
          onClick={() => handleSourceChange(opt.value)}
        >
          <i className={`fas ${opt.icon}`}></i>
          <span>{opt.label}</span>
        </button>
      ))}
    </div>
  );

  // Mobile: Collapsible UI
  if (isMobile) {
    return (
      <>
        {/* Backdrop - click to close */}
        {isExpanded && (
          <div className={styles.filterBackdrop} onClick={handleClose} />
        )}

        <div className={styles.container}>
          {/* Source filter pills - always visible on mobile too */}
          {sourcePills}

          <div className={styles.mobileHeader}>
            <div className={styles.filterDropdownWrapper}>
              <button
                className={styles.filterToggle}
                onClick={handleToggle}
                aria-expanded={isExpanded}
                aria-label="Toggle filters"
              >
                <i className="fas fa-filter"></i>
                <span>Lọc</span>
                {activeFilterCount > 0 && (
                  <span className={styles.filterBadge}>{activeFilterCount}</span>
                )}
                <i className={`fas fa-chevron-${isExpanded ? 'up' : 'down'}`}></i>
              </button>

              {isExpanded && (
                <div className={styles.mobileFilters}>
                  <Input
                    placeholder="Tìm task theo ID, tiêu đề..."
                    value={filters.search || ''}
                    onChange={(e) => handleChange('search', e.target.value)}
                    fullWidth
                  />

                  <Select
                    value={filters.priority || ''}
                    onChange={(e) => handleChange('priority', e.target.value)}
                    options={allPriorityOptions}
                    size="small"
                    fullWidth
                  />

                  <Select
                    value={filters.status || ''}
                    onChange={(e) => handleChange('status', e.target.value)}
                    options={allStatusOptions}
                    size="small"
                    fullWidth
                  />

                  <Select
                    value={filters.assignmentStrategy || ''}
                    onChange={(e) => handleChange('assignmentStrategy', e.target.value)}
                    options={allStrategyOptions}
                    size="small"
                    fullWidth
                  />

                  {/* Clear Filters Button */}
                  {hasActiveFilters && (
                    <button
                      className={styles.clearFiltersButton}
                      onClick={handleClearFilters}
                      type="button"
                    >
                      <i className="fas fa-times-circle"></i>
                      <span>Xóa bộ lọc</span>
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </>
    );
  }

  // Desktop: Original horizontal layout
  return (
    <div className={styles.container}>
      {/* Source filter pills */}
      {sourcePills}

      <div className={styles.filters}>
        <Input
          placeholder="Tìm task theo ID, tiêu đề..."
          value={filters.search || ''}
          onChange={(e) => handleChange('search', e.target.value)}
          className={styles.searchInput}
        />

        <Select
          value={filters.priority || ''}
          onChange={(e) => handleChange('priority', e.target.value)}
          className={styles.filterSelect}
          options={allPriorityOptions}
        />

        <Select
          value={filters.status || ''}
          onChange={(e) => handleChange('status', e.target.value)}
          className={styles.filterSelect}
          options={allStatusOptions}
        />

        <Select
          value={filters.assignmentStrategy || ''}
          onChange={(e) => handleChange('assignmentStrategy', e.target.value)}
          className={styles.filterSelect}
          options={allStrategyOptions}
        />

        {/* Clear Filters Button - Desktop */}
        {hasActiveFilters && (
          <button
            className={styles.clearFiltersButtonDesktop}
            onClick={handleClearFilters}
            type="button"
            title="Xóa bộ lọc"
          >
            <i className="fas fa-times-circle"></i>
            <span>Xóa bộ lọc</span>
          </button>
        )}
      </div>
    </div>
  );
};
