import React from 'react';
import { WorkflowStep } from '../../../models/Help';
import styles from './WorkflowStepsTable.module.css';

const roleClassMap: Record<string, string> = {
  user: styles.roleUser,
  staff: styles.roleStaff,
  lead: styles.roleLead,
  manager: styles.roleManager,
  system: styles.roleSystem,
};

interface WorkflowStepsTableProps {
  steps?: WorkflowStep[];
}

export const WorkflowStepsTable: React.FC<WorkflowStepsTableProps> = ({ steps = [] }) => {
  return (
    <div className={styles.tableWrapper}>
      <table className={styles.table}>
        <thead>
          <tr>
            <th className={styles.thStep}>Bước</th>
            <th className={styles.thName}>Tên bước</th>
            <th className={styles.thRoles}>Roles</th>
            <th className={styles.thActions}>Hành động</th>
            <th className={styles.thStatus}>Trạng thái</th>
            <th className={styles.thSla}>SLA</th>
          </tr>
        </thead>
        <tbody>
          {steps.map((step) => (
            <tr key={step.id} className={styles.row}>
              <td className={styles.tdStep}><strong>{step.step}</strong></td>
              <td className={styles.tdName}><strong>{step.name}</strong></td>
              <td className={styles.tdRoles}>
                {(step.roles ?? (step.role ? [step.role] : [])).map((role, i) => (
                  <span key={i} className={`${styles.roleBadge} ${roleClassMap[step.roleClasses?.[i] ?? ''] ?? ''}`}>
                    {role}
                  </span>
                ))}
              </td>
              <td className={styles.tdActions}>
                {step.actions.map((action, i) => (
                  <div key={i} className={styles.actionItem}>• {action}</div>
                ))}
              </td>
              <td className={styles.tdStatus}>
                {step.statuses?.map((s, i) => (
                  <span key={i} className={styles.statusBadge} style={{ background: s.bg, color: s.color }}>{s.label}</span>
                ))}
              </td>
            <td className={styles.tdSla}>{step.sla && step.sla !== '-' ? step.sla : '—'}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};
