import React from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import { PriorityDistribution } from '../../../models/Statistics';
import { Card } from '../../common/Card';
import styles from './PriorityChart.module.css';

// Register ChartJS components
ChartJS.register(ArcElement, Tooltip, Legend);

interface PriorityChartProps {
  data: PriorityDistribution;
}

export const PriorityChart: React.FC<PriorityChartProps> = ({ data }) => {
  const chartData = {
    labels: ['Khẩn cấp', 'Cao', 'Trung bình', 'Thấp'],
    datasets: [
      {
        data: [data.urgent, data.high, data.medium, data.low],
        backgroundColor: [
          'rgb(239, 68, 68)', // Urgent - red
          'rgb(249, 115, 22)', // High - orange
          'rgb(59, 130, 246)', // Medium - blue
          'rgb(156, 163, 175)', // Low - gray
        ],
        borderWidth: 2,
        borderColor: 'white',
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom' as const,
      },
      tooltip: {
        backgroundColor: 'rgba(0, 0, 0, 0.8)',
        padding: 12,
        callbacks: {
          label: function (context: any) {
            const label = context.label || '';
            const value = context.parsed || 0;
            const total = context.dataset.data.reduce((a: number, b: number) => a + b, 0);
            const percentage = ((value / total) * 100).toFixed(1);
            return `${label}: ${value} (${percentage}%)`;
          },
        },
      },
    },
  };

  return (
    <Card className={styles.chartCard}>
      <h3 className={styles.title}>
        <i className="fas fa-chart-pie" style={{ color: 'var(--warning-color)' }}></i>
        Phân bố theo mức độ
      </h3>
      <div className={styles.chartContainer}>
        <Doughnut data={chartData} options={options} />
      </div>
    </Card>
  );
};
